method valid_date(date: string) returns (result: bool)
    requires date != ""
    requires date.Length == 10
    requires date[2] == '-'
    requires date[5] == '-'
    requires date[0..2].IsDigit() && date[3..5].IsDigit() && date[6..10].IsDigit()
    ensures result == (ValidDateFormat(date))

    // Helper function to check the validity of the date
    function ValidDateFormat(date: string): bool
        requires date.Length == 10
        ensures (date[0..2].IsDigit() && date[3..5].IsDigit() && date[6..10].IsDigit())
        ensures (date[2] == '-' && date[5] == '-')
        ensures (MonthDays(date) > 0 && MonthDays(date) <= MaxDays(ParseMonth(date)))
    {
        var month := ParseMonth(date);
        var day := ParseDay(date);
        month >= 1 && month <= 12 && day >= 1 && day <= MaxDays(month)
    }

    // Extract month from the date string
    function ParseMonth(date: string): int
    {
        return (int)(date[0..2]);
    }

    // Extract day from the date string
    function ParseDay(date: string): int
    {
        return (int)(date[3..5]);
    }

    // Return max days in month
    function MaxDays(month: int): int
        requires month >= 1 && month <= 12
        ensures (month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) ==> result == 31
        ensures (month == 4 || month == 6 || month == 9 || month == 11) ==> result == 30
        ensures month == 2 ==> result <= 29
    {
        if month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12 then
            return 31;
        else if month == 4 || month == 6 || month == 9 || month == 11 then
            return 30;
        else
            return 29; // For February, assume 29 for the sake of this validation
    }
}
